/**
 * Words in Context (wic), rewritten to the Stellify question standard. Each sentence now describes a real,
 * documented subject (a study checked against its PubMed or Crossref record, or a public-domain text), so that
 * the vocabulary is tested in an accurate context. Literary items quote public-domain works exactly.
 */
import type { RawQuestion } from '@/lib/types';
import type { TrapCode } from '../distractors';

const CHECKED = '2026-11-27';
type Q = RawQuestion & { tags: (TrapCode | null)[] };
const BLANK = 'Which choice completes the text with the most logical and precise word or phrase?';
const MEANS = (w: string) => `As used in the text, what does the word “${w}” most nearly mean?`;
const WS = {
  emerson: 'https://en.wikisource.org/wiki/Essays%3A_First_Series/Self-Reliance',
  innocence: 'https://en.wikisource.org/wiki/The_Age_of_Innocence/Chapter_2',
  persuasion: 'https://en.wikisource.org/wiki/Persuasion/Chapter_XXIII',
  wild: 'https://en.wikisource.org/wiki/The_Call_of_the_Wild_(London)/Chapter_1',
  gatsby: 'https://en.wikisource.org/wiki/The_Great_Gatsby_(1925)/Chapter_1',
  walden: 'https://en.wikisource.org/wiki/Walden_(1854)_Thoreau/Where_I_Lived,_and_What_I_Lived_for',
  hope: 'https://en.wikisource.org/wiki/Poems%3A_Second_Series_(Dickinson)/Hope',
};

interface Spec {
  id: string; d: RawQuestion['d']; sub: string; passage: string; word?: string; choices: string[]; answer: number;
  tags: (TrapCode | null)[]; why: string[]; steps: string[]; cite: string; url: string; note: string;
}
function W(s: Spec): Q {
  const blank = !s.word;
  return {
    id: s.id, skill: 'wic', sub: s.sub, d: s.d, passage: s.passage, stem: blank ? BLANK : MEANS(s.word!), choices: s.choices,
    answer: s.answer, tags: s.tags, why: s.why, steps: s.steps,
    concept: blank
      ? 'In a sentence-completion question, the text contains a clue, often after a colon or a contrast word, that defines the missing word.'
      : 'Many words have several meanings; the context, not the most familiar meaning, decides which one the author intends.',
    strategy: blank
      ? 'Cover the choices, find the clue, and predict your own word; then choose the closest match.'
      : 'Replace the word with each choice and keep the one that preserves the sentence’s meaning.',
    trap: blank
      ? 'A word that fits part of the sentence but contradicts the clue, or one that is close in meaning but not precise.'
      : 'The word’s most common meaning, which often does not fit the context.',
    remember: blank ? 'Read past the blank: the clue usually follows it.' : 'Substitute, then reread the whole sentence.',
    meta: {
      source: { cite: s.cite, url: s.url, checked: CHECKED },
      review: {
        teacher: `AI teacher pass (Stellify): ${s.note}`,
        bias: 'AI bias and clarity pass (Stellify): the text supplies all needed context, no outside knowledge or cultural, regional or income assumptions are required, and the wording is plain with no double negatives.',
        date: CHECKED,
      },
    },
  };
}
const lit = (intro: string, excerpt: string) => `${intro}\n\n${excerpt}`;

